SELECT DATE_TRUNC('MONTH', event_time) AS activity_month, COUNT(*) FILTER (WHERE page = '/search') AS search_rows, ROUND(SUM(duration_sec) / NULLIF(COUNT(CASE WHEN event_type = 'purchase' THEN 1 END), 0), 2) AS duration_sec_per_purchase, PERCENTILE_APPROX(duration_sec, ARRAY(0.25, 0.5, 0.75)) AS duration_sec_quartiles, SUM(CASE WHEN page = '/cart' THEN duration_sec ELSE 0 END) AS cart_duration_sec, SORT_ARRAY(COLLECT_SET(event_type)) AS event_type_list FROM web_events GROUP BY DATE_TRUNC('MONTH', event_time) HAVING search_rows > 1;
